pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        vm.assume(_owner != address(0));
        address originalOwner = c.owner();
        vm.prank(address(c)); // admin is contract itself, so prank as contract
        bool success = c.setOwner(_owner);
        if (success) {
            assertEq(c.owner(), _owner);
        } else {
            assertEq(c.owner(), originalOwner);
        }
    }
}

