import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address admin, address newOwner) public {
        vm.assume(admin != address(0));
        vm.startPrank(admin);
        try c.setOwner(newOwner) returns (bool success) {
            assertTrue(success);
        } catch {
            // If call reverts (e.g., not admin), we don't care about return value
            // Just pass — this test only asserts when the call succeeds
        }
        vm.stopPrank();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));

        address currentOwner = c.owner();
        vm.prank(actor);
        c.setOwner(actor);
        address newOwner = c.owner();

        // In the reference contract, only the admin can change the owner.
        // Since 'actor' is not the original deployer (admin), the owner must remain unchanged.
        // The buggy version bypasses this check, so fuzzer can find an actor that changes the owner.
        assertTrue(newOwner == currentOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this)); // deployer is admin; ensure caller is not admin
        vm.assume(caller != address(0));
        address originalOwner = c.owner();
        vm.prank(caller);
        c.setOwner(newOwner);
        assertTrue(c.owner() == originalOwner);
    }
}
